// 솔 야누스(새벽) 실제 게임 스크린샷 2장(2026-11-15, 사용자가 Win+Shift+S로 잘라 보냄). 남색 바탕에 보라색 원, 가운데 노란 남은 시간.
// 게임 UI 크기 때문에 아이콘이 기본(32px)의 약 1.4배. RGB 행 우선으로 이어 붙여 brotli 뒤 base64
import zlib from 'node:zlib';
export const JANUS_SHOTS=[
  {text:'28',w:60,h:60,rgb:''},
  {text:'32',w:66,h:59,rgb:''},
];
// RGBA Uint8ClampedArray
export function shotPx(o){
  const raw=zlib.brotliDecompressSync(Buffer.from(o.rgb,'base64')), px=new Uint8ClampedArray(o.w*o.h*4);
  for(let i=0,j=0;i<o.w*o.h;i++,j+=3){ px[i*4]=raw[j]; px[i*4+1]=raw[j+1]; px[i*4+2]=raw[j+2]; px[i*4+3]=255; }
  return px;
}
